        {"kind": "metric", "sql": "SELECT metric, round(sum(value),1) AS total, count(*) AS n FROM abnormal_metrics_sum WHERE attr_k8s_pod_name = 'ts-travel2-service-cb84684f8-cqwpw' AND metric = 'container.cpu.time' GROUP BY 1 UNION ALL SELECT metric, round(sum(value),1), count(*) FROM normal_metrics_sum WHERE attr_k8s_pod_name = 'ts-travel2-service-cb84684f8-cqwpw' AND metric = 'container.cpu.time' GROUP BY 1", "claim": "travel2 pod container CPU time fell from about 21,627 in normal to about 2 in the abnormal window."},
        {"kind": "metric", "sql": "SELECT metric, round(avg(value),1) AS avgv, round(max(value),1) AS maxv FROM abnormal_metrics WHERE attr_k8s_pod_name = 'ts-travel2-service-cb84684f8-cqwpw' AND metric IN ('k8s.container.restarts','container.memory.usage') GROUP BY 1", "claim": "travel2 container restarted (restarts=1) and its memory usage stayed near 0.6 MB, versus about 795 MB normally."}
      ]
    }
