    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [
      {"kind": "trace", "sql": "SELECT attr_http_response_status_code AS code, count(*) AS n, round(approx_quantile(duration,0.5)/1e6,1) AS p50_ms FROM abnormal_traces WHERE service_name = 'ts-travel-plan-service' AND span_name = 'POST' AND attr_span_kind = 'Client' GROUP BY 1", "claim": "Travel-plan's calls to route-plan returned 504 after about 60 s in 3 cases; route-plan's cheapestRoute server spans returned 500."}
    ]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [
      {"kind": "trace", "sql": "SELECT attr_http_response_status_code AS code, count(*) AS n, round(approx_quantile(duration,0.5)/1e6,1) AS p50_ms FROM abnormal_traces WHERE service_name = 'ts-ui-dashboard' AND attr_span_kind = 'Server' AND attr_http_response_status_code >= 400 GROUP BY 1", "claim": "The ui-dashboard user endpoint returned 503 after about 3.6 s p50 for about 30 requests in the abnormal window."}
    ]}
  ]
}
